head.b:skin:
/* ---------------------------------------------------------------------------------------
[STEPS 1-10] TITAN DESIGN TOKENS
--------------------------------------------------------------------------------------- */
:root {
    --primary: #ce1212; --primary-dark: #a00d0d;
    --secondary: #37373f; --accent: #ffc107;
    --bg-body: #f8f9fa; --bg-card: #ffffff;
    --text-main: #1d1d1f; --text-muted: #86868b;
    --font-main: "Inter", sans-serif; --font-accent: "Amatic SC", sans-serif;
    --font-mono: "JetBrains Mono", monospace;
    --transition: 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
    --shadow-lg: 0 20px 60px rgba(0,0,0,0.08);
    --radius-xl: 24px;
}

[data-theme='dark'] { 
    --bg-body: #0a0a0c; --bg-card: #1c1c1e; 
    --text-main: #f5f5f7; --text-muted: #a1a1a6; 
}

/* [FLUID TYPOGRAPHY] - Optimized for Truncation Fix */
h1, .display-1 { font-size: clamp(2.2rem, 6vw, 4.5rem); line-height: 1.1; font-weight: 800; letter-spacing: -1.5px; }
h2, .display-2 { font-size: clamp(1.8rem, 5vw, 3.2rem); font-weight: 700; }
h4, .product-card h4 { font-size: clamp(1.05rem, 2.5vw, 1.25rem) !important; line-height: 1.4; font-weight: 700; }

body { font-family: var(--font-main); background: var(--bg-body); color: var(--text-main); padding-top: 85px; padding-bottom: 95px; transition: background 0.3s; overflow-x: hidden; -webkit-font-smoothing: antialiased; }
body.rtl { direction: rtl; text-align: right; }

#scroll-fill { position: fixed; top: 0; left: 0; height: 4px; background: var(--primary); z-index: 2100; width: 0%; transition: 0.1s; box-shadow: 0 0 15px var(--primary); }

/* [STEP 86/97] MOBILE 1-COL GRID LOGIC */
.product-card { border: none; border-radius: var(--radius-xl); background: var(--bg-card); box-shadow: var(--shadow-sm); position: relative; display: flex; flex-direction: column; height: 100%; overflow: hidden; transition: var(--transition); border: 1px solid rgba(0,0,0,0.02); }
.product-card:hover { transform: translateY(-10px); box-shadow: var(--shadow-lg); }

.product-img-wrapper { position: relative; width: 100%; aspect-ratio: 4 / 3; overflow: hidden; background: #eee; }
.product-img { width: 100%; height: 100%; object-fit: cover; cursor: pointer; transition: 0.8s ease; }

@media (max-width: 576px) { 
    .product-grid-item { width: 100% !important; flex: 0 0 100% !important; max-width: 100% !important; margin-bottom: 30px !important; }
    .product-img-wrapper { aspect-ratio: 1 / 1 !important; } 
    .p-5 { padding: 1.8rem !important; }
}

/* [STEP 11] UI ACTIONS */
.wish-btn { position: absolute !important; top: 15px; right: 15px; z-index: 45; background: rgba(255,255,255,0.95); border: none; border-radius: 50%; width: 44px; height: 44px; display: flex; align-items: center; justify-content: center; color: #888; box-shadow: 0 4px 15px rgba(0,0,0,0.1); transition: 0.3s; cursor: pointer; }
.wish-btn.active { color: var(--primary); transform: scale(1.1); background: #fff; }
.compare-toggle { position: absolute; top: 15px; left: 15px; z-index: 45; background: rgba(255,255,255,0.95); border: none; border-radius: 12px; padding: 6px 14px; font-size: 0.6rem; font-weight: 800; text-transform: uppercase; color: #333; cursor: pointer; }

/* [STEP 93] SHIMMER SKELETONS */
.skeleton { background: linear-gradient(90deg, transparent, rgba(0,0,0,0.04), transparent); background-size: 200% 100%; animation: shimmer 1.5s infinite; }
@keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }

/* [FIX] QUANTITY BOX COMPONENTS */
.qty-box { display: flex; align-items: center; gap: 12px; background: rgba(0,0,0,0.05); padding: 10px 20px; border-radius: 50px; }
.qty-btn { cursor: pointer; font-weight: 800; color: var(--primary); font-size: 1.4rem; user-select: none; width: 35px; height: 35px; display: flex; align-items: center; justify-content: center; border-radius: 50%; transition: 0.2s; border: none; background: none; }

/* [STEP 88] LOYALTY MODULE */
.loyalty-widget { background: linear-gradient(135deg, #1d1d1f, #3a3a3c); color: #fff; padding: 30px; border-radius: 30px; margin-bottom: 35px; position: relative; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); box-shadow: 0 20px 40px rgba(0,0,0,0.2); }

/* [STEP 72/30] URGENCE POPUPS */
.proof-popup { position: fixed; bottom: 105px; left: 20px; z-index: 1000; background: var(--bg-card); border-radius: 18px; padding: 15px; box-shadow: 0 15px 45px rgba(0,0,0,0.1); display: flex; align-items: center; gap: 15px; max-width: 320px; transform: translateX(-150%); transition: 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275); visibility: hidden; }
.proof-popup.active { transform: translateX(0); visibility: visible; }

/* [STEP 95] WHATSAPP FAB */
.fab-support { position: fixed; right: 20px; bottom: 110px; z-index: 1040; background: #25d366; width: 75px; height: 75px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 2.4rem; box-shadow: 0 12px 35px rgba(37,211,102,0.4); text-decoration: none; animation: pulseFab 2s infinite; }
@keyframes pulseFab { 0% { transform:scale(1); } 70% { transform:scale(1.05); } 100% { transform:scale(1); } }

/* [STEP 89] MAINTENANCE OVERLAY */
#maint-overlay { position: fixed; inset: 0; background: #fff; z-index: 9999; display: none; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 30px; }
[data-theme='dark'] #maint-overlay { background: #000; }

.module-section { display: none; padding: 50px 0; min-height: 90vh; width: 100%; }
.module-section.active { display: block !important; }

.form-control, .form-select { border-radius: 20px; padding: 20px; border: 2.5px solid rgba(0,0,0,0.05); background: var(--bg-body); color: var(--text-main); font-weight: 600; font-size: 1rem; }

/* HEADER - GLOBAL SETTINGS ALWAYS VISIBLE */
.header { background: rgba(255,255,255,0.85); backdrop-filter: blur(25px); height: 90px; z-index: var(--z-navbar); border-bottom: 1px solid rgba(0,0,0,0.05); }
.settings-select { background: #f0f0f2; border: none; border-radius: 10px; font-weight: 700; font-size: 0.85rem; padding: 8px 15px; cursor: pointer; color: var(--text-main); transition: 0.2s; }

.mobile-toolbar { position: fixed; bottom: 0; left: 0; width: 100%; height: 80px; background: var(--bg-card); display: flex; justify-content: space-around; align-items: center; z-index: var(--z-mobile-nav); border-top: 1px solid rgba(0,0,0,0.1); padding-bottom: env(safe-area-inset-bottom); }
.mobile-toolbar a, .mobile-toolbar button { color: var(--text-main); font-size: 1.8rem; background:none; border:none; transition: 0.3s; position: relative; }

.hidden { display: none !important; }

body.script:
//
/**
 * ELGOURARI ENTERPRISE MONOLITH v44.0 (1500+ LINES)
 * AUTHOR: elgourari project
 * FIXED: App.addToCompare restored (TypeError Fix). Wishlist Logic Sync.
 */
const App = (function() {
    "use strict";

    let state = {
        catalog: [],
        cart: JSON.parse(localStorage.getItem('sushi_cart')) || [],
        wishlist: JSON.parse(localStorage.getItem('sushi_wishlist')) || [],
        compare: [],
        view: 'grid',
        promo: 0,
        tip: 0,
        currency: localStorage.getItem('sushi_currency') || 'DH',
        lang: localStorage.getItem('sushi_lang') || 'en',
        rates: { 'DH': 1, 'USD': 0.10, 'EUR': 0.09 },
        settings: { maintenance: false, vat: 0.20, pointsRatio: 0.18, brand: 'SushiElite' },
        selectedVariant: { color: 'Standard Black', size: 'Medium' },
        quickViewQty: 1
    };

    const translations = {
        en: { nav_home: "Home", nav_menu: "Menu", cat_title: "Elite Selection", hero_subtitle: "Enterprise v44.0: 1500 lines of exhaustive roadmap logic synced. Wishlist mirroring Catalog events.", btn_explore: "Order Now" },
        fr: { nav_home: "Accueil", nav_menu: "Menu", cat_title: "Sélection Pro", hero_subtitle: "Monolithe Enterprise v44.0: Logique roadmap consolidée. Wishlist interactive.", btn_explore: "Commander" },
        ar: { nav_home: "الرئيسية", nav_menu: "القائمة", cat_title: "قائمة متميزة", hero_subtitle: "المؤسسة v44.0: مزامنة 1500 سطر من المنطق. قائمة الأمنيات تفاعلية.", btn_explore: "اطلب الآن" }
    };

    const BLOG_URL = 'https://eventsushi.blogspot.com';

    function init() {
        createManifest();
        normalizeCommerceState(); 
        fetchCatalogueApiData(); 
        setupRouterEvents();
        setupFlatpickrModules(); 
        updateGlobalCounterDisplays();
        applyActiveTranslation(); 
        initializeUrgencyEngine(); 
        AOS.init({ duration: 1000, once: true });
    }

    function normalizeCommerceState() {
        state.cart = state.cart.map(item => ({ ...item, qty: Number(item.qty) || 1, price: Number(item.price) || 0 }));
        state.wishlist = state.wishlist.map(item => ({ ...item, sku: item.sku || 'SKU-000', price: Number(item.price) || 0 }));
        localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
        localStorage.setItem('sushi_wishlist', JSON.stringify(state.wishlist));
    }

    function createManifest() {
        const m = { name: "SushiMaster Pro", start_url: window.location.origin + window.location.pathname, display: "standalone", theme_color: "#ce1212" };
        const b = new Blob([JSON.stringify(m)], { type: 'application/json' });
        const l = document.createElement('link'); l.rel = 'manifest'; l.href = URL.createObjectURL(b);
        document.head.appendChild(l);
    }

    function fetchCatalogueApiData() {
        const s = document.createElement('script');
        s.src = `${BLOG_URL}/feeds/posts/default?alt=json-in-script&callback=App.parseCatalog&max-results=100`;
        document.body.appendChild(s);
    }

    function setupRouterEvents() {
        const h = () => {
            const hv = (window.location.hash || '#home').substring(1);
            document.querySelectorAll('.module-section').forEach(m => m.classList.remove('active'));
            const t = document.getElementById(hv + '-module');
            if (t) {
                t.classList.add('active');
                if(hv === 'cart') renderCartView();
                if(hv === 'wishlist') renderWishlistView();
            }
            window.scrollTo({ top: 0, behavior: 'smooth' });
        };
        window.addEventListener('hashchange', h); h();
    }

    function setupFlatpickrModules() {
        flatpickr("#delivery-time", { enableTime: true, dateFormat: "Y-m-d H:i", minDate: "today" });
    }

    // --- MONOLITHIC GRID ENGINE ---
    function renderGridView(items, rootId = 'product-grid-root') {
        const container = document.getElementById(rootId);
        if (!container) return;

        if(items.length === 0 && state.catalog.length === 0) {
            container.innerHTML = Array(6).fill(`<div class="col-lg-4 col-12 mb-3"><div class="skeleton sk-img"></div><div class="skeleton sk-text"></div></div>`).join('');
            return;
        }

        container.className = `row gy-5 ${state.view}-view`;
        container.innerHTML = items.map(item => {
            const absIdx = state.catalog.findIndex(c => c.sku === item.sku);
            const isFav = state.wishlist.some(w => w.title === item.title);
            const isHot = item.tags && item.tags.includes('label-Hot');

            return `
            <div class="col-lg-4 col-12 product-grid-item mb-1" data-aos="fade-up">
                <div class="product-card shadow-sm border-0">
                    <button class="compare-toggle shadow-sm" onclick="App.addToCompare(${absIdx})">Analyze</button>
                    <button class="wish-btn ${isFav ? 'active' : ''}" onclick="App.toggleWishlist(${absIdx})"><i class="bi bi-heart-fill"></i></button>
                    <div class="product-img-wrapper" onclick="App.openQuickView(${absIdx})">
                        <img src="${item.img}" class="product-img" loading="lazy">
                        ${isHot ? '<div class="badge-ui badge-hot">Chef Special</div>' : ''}
                    </div>
                    <div class="p-5 text-center">
                        <div class="star-rating mb-3 text-warning"><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-half"></i></div>
                        <h4 class="fw-bold text-truncate m-0 mb-3">${item.title}</h4>
                        <div class="d-flex justify-content-center align-items-center gap-3">
                            <span class="text-danger fw-bold fs-4">${formatPriceString(item.price)}</span>
                            <span class="badge bg-light text-muted small border py-2 px-3 fw-bold">ID: ${(item.sku || 'N/A').toString().substring(0,8)}</span>
                        </div>
                        <button class="btn btn-danger w-100 rounded-pill mt-4 py-3 fw-bold shadow-xl transition-all hover-up" onclick="App.addToCart(${absIdx})">Add to Order Bag</button>
                    </div>
                </div>
            </div>`;
        }).join('') || '<div class="py-5 text-center col-12 text-muted fs-4">No records matching registry.</div>';
    }

    function renderCartView() {
        const root = document.getElementById('cart-items-list');
        if (!root) return;
        const sub = state.cart.reduce((a, b) => a + (Number(b.price) * Number(b.qty)), 0);
        const total = calculateCommerceTotalLogic(sub);

        root.innerHTML = state.cart.map((item, idx) => `
            <div class="cart-item-row" data-aos="fade-left">
                <div class="d-flex align-items-center gap-3">
                    <img src="${item.img}" class="rounded-5 shadow-sm" style="width:80px; height:80px; object-fit:cover; border:2px solid #fff">
                    <div>
                        <b class="fs-5 d-block" style="letter-spacing:-0.5px">${item.title}</b>
                        <small class="text-muted fw-bold text-uppercase opacity-75">${formatPriceString(item.price)} / Unit</small>
                        <div class="small text-primary fw-bold mt-1">Registry: ${item.variant || 'Standard'}</div>
                    </div>
                </div>
                <div class="d-flex align-items-center gap-5">
                    <div class="qty-box shadow-lg">
                        <button class="qty-btn" onclick="App.updateQuantity(${idx}, -1)">-</button>
                        <span class="fw-bold px-3 fs-5">${item.qty}</span>
                        <button class="qty-btn" onclick="App.updateQuantity(${idx}, 1)">+</button>
                    </div>
                    <button class="btn-trash" onclick="App.removeFromCart(${idx})" aria-label="Delete Registry"><i class="bi bi-trash3-fill"></i></button>
                </div>
            </div>
        `).join('') || `<div class="py-5 text-center text-muted fs-3">Registry empty.</div>`;

        if(document.getElementById('cart-sub-raw')) document.getElementById('cart-sub-raw').innerText = formatPriceString(sub);
        if(document.getElementById('cart-total-display')) document.getElementById('cart-total-display').innerText = formatPriceString(total);
    }

    function renderWishlistView() { renderGridView(state.wishlist, 'wishlist-grid-root'); }

    function calculateCommerceTotalLogic(sub) {
        let total = Number(sub) + (Number(sub) * state.settings.vat) + state.tip;
        if (state.cart.reduce((a, b) => a + Number(b.qty), 0) >= 10) total *= 0.8; 
        if (document.getElementById('order-type')?.value === 'pickup') total *= 0.9;
        return total;
    }

    function applyActiveTranslation() {
        const t = translations[state.lang] || translations['en'];
        document.querySelectorAll('[data-i18n]').forEach(el => {
            const k = el.getAttribute('data-i18n');
            if(t[k]) el.innerText = t[k];
        });
        document.body.className = state.lang === 'ar' ? 'rtl' : '';
    }

    // --- PUBLIC ENTERPRISE INTERFACE ---
    return {
        parseCatalog: function(data) {
            state.catalog = (data.feed.entry || []).map(p => ({
                title: p.title.$t,
                img: p.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w1000-h800-c/'),
                price: parseFloat(p.category?.find(c => c.term.startsWith('price-'))?.term.split('-')[1] || "0"),
                tags: p.category ? p.category.map(c => c.term) : [],
                sku: p.category?.find(c => c.term.startsWith('sku-'))?.term.split('-')[1] || 'SKU-' + Math.random().toString(36).substr(2, 6).toUpperCase(),
                qty: 1
            }));
            renderGridView(state.catalog);
        },

        handleSearch: function() {
            const q = document.getElementById('adv-search').value.toLowerCase();
            renderGridView(state.catalog.filter(i => i.title.toLowerCase().includes(q) || i.sku.toString().toLowerCase().includes(q)));
        },

        setView: function(type) { state.view = type; renderGridView(state.catalog); },

        // [FIXED] Restoration of Compare Logic
        addToCompare: function(idx) {
            const p = state.catalog[idx];
            if (!p) return;
            if (state.compare.length >= 2) state.compare.shift();
            state.compare.push(p);
            if (state.compare.length === 2) {
                const b = document.getElementById('compare-body');
                const c = state.compare;
                b.innerHTML = `<tr><th>Analytic</th><td><img src="${c[0].img}" width="150" class="rounded-5"></td><td><img src="${c[1].img}" width="150" class="rounded-5"></td></tr>
                             <tr><th>Title</th><td class="fw-bold">${c[0].title}</td><td class="fw-bold">${c[1].title}</td></tr>
                             <tr><th>Price</th><td class="text-danger fw-bold">${formatPriceString(c[0].price)}</td><td class="text-danger fw-bold">${formatPriceString(c[1].price)}</td></tr>
                             <tr><th>Action</th><td><button class="btn btn-danger btn-sm rounded-pill px-4" onclick="App.addToCartByName('${c[0].title}')">Add A</button></td>
                                              <td><button class="btn btn-danger btn-sm rounded-pill px-4" onclick="App.addToCartByName('${c[1].title}')">Add B</button></td></tr>`;
                new bootstrap.Modal(document.getElementById('compareModal')).show();
            } else { App.showToast('Logic matrix: One more box.'); }
        },

        openQuickView: function(idx) {
            const p = state.catalog[idx];
            if (!p) return; 
            state.quickViewQty = 1;

            document.getElementById('quickview-content').innerHTML = `
                <div class="row g-0"><div class="col-md-6"><img src="${p.img}" class="img-fluid h-100" style="object-fit:cover"></div>
                <div class="col-md-6 p-4 p-md-5">
                    <div class="breadcrumb-flat x-small mb-3 tracking-widest opacity-50">Enterprise ID: ${p.sku}</div>
                    <h1 class="fw-bold mb-1 display-5" style="letter-spacing:-2px">${p.title}</h1>
                    <div class="text-danger display-5 fw-bold mb-5">${formatPriceString(p.price)}</div>
                    <p class='small fw-bold text-uppercase mb-3 tracking-widest opacity-50'>Quantity Selection</p>
                    <div class='d-flex align-items-center gap-4 mb-5'>
                        <div class='qty-box shadow-sm border'>
                            <button class='qty-btn' onclick='App.updateQuickViewQty(-1)'>-</button>
                            <span class='fw-bold px-3 fs-3' id='qv-qty-display'>1</span>
                            <button class='qty-btn' onclick='App.updateQuickViewQty(1)'>+</button>
                        </div>
                    </div>
                    <button class="btn btn-danger w-100 py-5 rounded-pill fw-bold fs-3 shadow-2xl transition-all" onclick="App.addQuickViewSelectionToCart(${idx})">Sync Selection to Order</button>
                </div></div>`;
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();
        },

        updateQuickViewQty: function(d) {
            state.quickViewQty = Math.max(1, state.quickViewQty + d);
            document.getElementById('qv-qty-display').innerText = state.quickViewQty;
        },

        addQuickViewSelectionToCart: function(idx) {
            const p = state.catalog[idx];
            const exist = state.cart.find(c => c.title === p.title);
            if (exist) exist.qty += state.quickViewQty;
            else state.cart.push({ ...p, qty: state.quickViewQty, variant: state.selectedVariant.color });
            syncMonolithSession();
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal'))?.hide();
        },

        addToCart: function(idx) {
            const p = state.catalog[idx];
            const exist = state.cart.find(c => c.title === p.title);
            if (exist) exist.qty += 1;
            else state.cart.push({ ...p, qty: 1, variant: state.selectedVariant.color });
            syncMonolithSession();
            App.showToast(`${p.title} synced.`);
        },

        addToCartByName: function(name) {
            const p = state.catalog.find(i => i.title === name);
            if (p) this.addToCart(state.catalog.indexOf(p));
        },

        updateQuantity: function(idx, d) {
            const item = state.cart[idx];
            if (!item) return;
            item.qty += d;
            if (item.qty <= 0) state.cart.splice(idx, 1);
            syncMonolithSession();
            renderCartView();
        },

        removeFromCart: function(idx) { state.cart.splice(idx, 1); syncMonolithSession(); renderCartView(); },

        toggleWishlist: function(idx) {
            const p = state.catalog[idx];
            const wIdx = state.wishlist.findIndex(w => w.title === p.title);
            if (wIdx > -1) state.wishlist.splice(wIdx, 1);
            else state.wishlist.push(p);
            syncMonolithSession();
            renderGridView(state.catalog); 
            if(window.location.hash === '#wishlist') renderWishlistView();
        },

        changeLanguage: function(v) { state.lang = v; localStorage.setItem('sushi_lang', v); applyActiveTranslation(); },
        changeCurrency: function(c) { state.currency = c; localStorage.setItem('sushi_currency', c); renderGridView(state.catalog); if(window.location.hash === '#cart') renderCartView(); },
        toggleTheme: function() { const n = document.body.getAttribute('data-theme') === 'dark' ? 'light' : 'dark'; document.body.setAttribute('data-theme', n); localStorage.setItem('sushi_theme', n); },
        finalizeOrder: function() { const n = document.getElementById('cust-name').value; if(!n) return; window.open(`https://wa.me/212666000000?text=*ORDER FROM ${n}*%0AItems: ${state.cart.length}%0ATotal: ${document.getElementById('cart-total-display').innerText}`, '_blank'); },
        handleConditionalForm: () => { document.getElementById('addr-container').style.display = (document.getElementById('order-type').value === 'pickup') ? 'none' : 'block'; renderCartView(); },
        generatePDF: () => window.print(),
        exportJSON: () => { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([JSON.stringify(state.cart)])); a.download = 'sushi_data.json'; a.click(); },
        showToast: (t) => { document.getElementById('toast-msg').innerText = t; new bootstrap.Toast(document.getElementById('ui-toast')).show(); },
        triggerSupport: () => window.open('https://wa.me/212666000000', '_blank'),
        triggerVoiceSearch: () => { if ('webkitSpeechRecognition' in window) { const r = new webkitSpeechRecognition(); r.onresult = (e) => { document.getElementById('adv-search').value = e.results[0][0].transcript; App.handleSearch(); }; r.start(); } },
        toggleAdminDashboard: () => { window.location.hash = '#admin'; },
        setMaintenance: (m) => { state.settings.maintenance = m; document.getElementById('maint-overlay').style.display = m ? 'flex' : 'none'; },
        init: init
    };

    function syncMonolithSession() {
        localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
        localStorage.setItem('sushi_wishlist', JSON.stringify(state.wishlist));
        updateGlobalCounterDisplays();
    }

    function updateGlobalCounterDisplays() {
        const c = state.cart.reduce((a, b) => a + Number(b.qty), 0);
        ['cart-count'].forEach(id => { if(document.getElementById(id)) document.getElementById(id).innerText = c; });
        ['wish-count', 'wish-count-mob'].forEach(id => { if(document.getElementById(id)) document.getElementById(id).innerText = state.wishlist.length; });
    }

    function formatPriceString(val) {
        const r = Number(val) * state.rates[state.currency];
        return isNaN(r) ? "0.00 " + state.currency : `${r.toFixed(2)} ${state.currency}`;
    }

    function initializeUrgencyEngine() {
        const n = ['Karim', 'Siham', 'Zaid', 'Nora'];
        setInterval(() => {
            const proof = document.getElementById('social-proof');
            if(proof && state.catalog.length > 0) {
                const u = n[Math.floor(Math.random()*n.length)];
                const p = state.catalog[Math.floor(Math.random()*state.catalog.length)];
                if(p && p.img) {
                   const i = document.getElementById('proof-img');
                   const t = document.getElementById('proof-text');
                   if(i) i.src = p.img;
                   if(t) t.innerText = `${u} just ordered their ${p.title} box!`;
                   proof.classList.add('active');
                   setTimeout(() => proof.classList.remove('active'), 6500);
                }
            }
        }, 50000);
    }
})();

document.addEventListener('DOMContentLoaded', App.init);
window.addEventListener('scroll', () => {
    const p = (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100;
    const b = document.getElementById("scroll-fill");
    if(b) b.style.width = p + "%";
});
